/**
 * Parses free-text supplier invoice payment terms into net days and
 * computes the corresponding due date.
 *
 * Supported formats (case-insensitive, surrounding whitespace ignored):
 *   - "NET" followed by 1 to 3 digits, with or without whitespace
 *     in between (e.g. "NET 30", "net30", "Net  45")
 *   - "DUE ON RECEIPT" (0 days)
 *
 * Exceptions:
 *   - TermsOutOfRangeException: net days above 180
 *   - UnsupportedTermsException: anything else, including null/blank input
 */
public inherited sharing class PaymentTerms {

    private static final Integer MAX_NET_DAYS = 180;
    private static final Integer DUE_ON_RECEIPT_DAYS = 0;

    // Matches the whole (trimmed, uppercased) string: NET + optional
    // whitespace + 1 to 3 digits.
    private static final Pattern NET_DAYS_PATTERN =
        Pattern.compile('NET\\s*(\\d{1,3})');

    /**
     * Parses payment terms text into a number of net days.
     *
     * @param terms the free-text payment terms, e.g. "NET 30"
     * @return the number of net days (0 for "DUE ON RECEIPT")
     * @throws TermsOutOfRangeException if the parsed day count exceeds 180
     * @throws UnsupportedTermsException if the input is null, blank, or unrecognized
     */
    public static Integer parseNetDays(String terms) {
        // Preserve the original input for error messages; null stays null.
        String original = terms;

        String cleaned = terms == null ? null : terms.trim();
        if (cleaned == null || cleaned.length() == 0) {
            throw new UnsupportedTermsException(
                'Unsupported payment terms: ' + original);
        }

        String normalized = cleaned.toUpperCase();

        if (normalized == 'DUE ON RECEIPT') {
            return DUE_ON_RECEIPT_DAYS;
        }

        Matcher matcher = NET_DAYS_PATTERN.matcher(normalized);
        if (matcher.matches()) {
            Integer days = Integer.valueOf(matcher.group(1));
            if (days > MAX_NET_DAYS) {
                throw new TermsOutOfRangeException(
                    'Net days out of range: ' + days);
            }
            return days;
        }

        throw new UnsupportedTermsException(
            'Unsupported payment terms: ' + original);
    }

    /**
     * Computes the invoice due date based on free-text payment terms.
     *
     * @param invoiceDate the invoice date
     * @param terms the free-text payment terms, e.g. "NET 30"
     * @return the invoice date plus the parsed number of net days
     * @throws TermsOutOfRangeException if the parsed day count exceeds 180
     * @throws UnsupportedTermsException if the terms are null, blank, or unrecognized
     */
    public static Date dueDate(Date invoiceDate, String terms) {
        Integer days = parseNetDays(terms);
        return invoiceDate.addDays(days);
    }
}
