/**
 * RecordSearchService
 *
 * Dynamic, injection-safe, security-aware record finder.
 * Runs a single SOQL query against any object with simple equality filters,
 * honoring the running user's object/field-level security and record sharing.
 */
public with sharing class RecordSearchService {

    /** The only exception type ever thrown by this service. */
    public class SearchException extends Exception {}

    private static final Integer MIN_ROWS = 1;
    private static final Integer MAX_ROWS = 200;

    /**
     * Searches an object with simple equality filters.
     *
     * @param objectApiName API name of the object to query (case-insensitive).
     * @param fields        List of field API names to include in SELECT (case-insensitive).
     * @param filters       Map of field API name -> value; combined with AND. Null/empty = no WHERE.
     * @param orderByField  Field API name to sort by, ascending; ignored when blank.
     * @param maxRows       LIMIT value, must be between 1 and 200.
     * @return List<SObject> of matching records, respecting sharing and FLS.
     * @throws SearchException for any invalid input, metadata/FLS problem or query failure.
     */
    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {

        // --- maxRows validation -------------------------------------------------
        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException('maxRows must be between ' + MIN_ROWS + ' and ' + MAX_ROWS + '.');
        }

        // --- requested fields validation ----------------------------------------
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields must not be null or empty.');
        }

        // --- object validation and read access ----------------------------------
        Schema.DescribeSObjectResult objectDescribe = describeAccessibleObject(objectApiName);
        Map<String, Schema.SObjectField> fieldsByLowerName = buildFieldMap(objectDescribe);

        // --- SELECT list (Id is always included; duplicates removed) -------------
        List<String> selectFields = new List<String>{'Id'};
        Set<String> seen = new Set<String>{'id'};
        for (String fieldName : fields) {
            if (String.isBlank(fieldName)) {
                throw new SearchException('Field name must not be blank.');
            }
            String key = fieldName.trim().toLowerCase();
            Schema.SObjectField fieldToken = fieldsByLowerName.get(key);
            if (fieldToken == null) {
                throw new SearchException('Field is not valid for object ' + objectDescribe.getName() + ': ' + fieldName);
            }
            if (!fieldToken.getDescribe().isAccessible()) {
                throw new SearchException('No read access to field: ' + fieldName);
            }
            if (key != 'id' && !seen.contains(key)) {
                seen.add(key);
                selectFields.add(fieldName.trim());
            }
        }

        // --- ORDER BY validation --------------------------------------------------
        String orderByClause = '';
        if (String.isNotBlank(orderByField)) {
            Schema.SObjectField orderFieldToken = fieldsByLowerName.get(orderByField.trim().toLowerCase());
            if (orderFieldToken == null) {
                throw new SearchException('Order by field is not valid for object ' + objectDescribe.getName() + ': ' + orderByField);
            }
            Schema.DescribeFieldResult orderFieldDescribe = orderFieldToken.getDescribe();
            if (!orderFieldDescribe.isAccessible()) {
                throw new SearchException('No read access to order by field: ' + orderByField);
            }
            if (!orderFieldDescribe.isSortable()) {
                throw new SearchException('Order by field cannot be sorted: ' + orderByField);
            }
            orderByClause = ' ORDER BY ' + orderByField.trim() + ' ASC';
        }

        // --- WHERE conditions (values are bound, never inlined/concatenated) ------
        Map<String, Object> bindValues = new Map<String, Object>();
        List<String> conditions = new List<String>();
        if (filters != null && !filters.isEmpty()) {
            Integer bindIndex = 0;
            for (String filterField : filters.keySet()) {
                if (String.isBlank(filterField)) {
                    throw new SearchException('Filter field name must not be blank.');
                }
                Schema.SObjectField filterFieldToken = fieldsByLowerName.get(filterField.trim().toLowerCase());
                if (filterFieldToken == null) {
                    throw new SearchException('Filter field is not valid for object ' + objectDescribe.getName() + ': ' + filterField);
                }
                Schema.DescribeFieldResult filterFieldDescribe = filterFieldToken.getDescribe();
                if (!filterFieldDescribe.isAccessible()) {
                    throw new SearchException('No read access to filter field: ' + filterField);
                }
                if (!filterFieldDescribe.isFilterable()) {
                    throw new SearchException('Filter field cannot be filtered: ' + filterField);
                }
                Object filterValue = filters.get(filterField);
                if (filterValue == null) {
                    // Null literal is safe and avoids null-binding edge cases.
                    conditions.add(filterField.trim() + ' = null');
                } else {
                    String bindName = 'fv' + bindIndex++;
                    bindValues.put(bindName, filterValue);
                    conditions.add(filterField.trim() + ' = :' + bindName);
                }
            }
        }

        // --- Assemble the single query --------------------------------------------
        String query = 'SELECT ' + String.join(selectFields, ', ')
                     + ' FROM ' + objectApiName.trim();
        if (!conditions.isEmpty()) {
            query += ' WHERE ' + String.join(conditions, ' AND ');
        }
        if (orderByClause != '') {
            query += orderByClause;
        }
        // maxRows is a validated Integer, so plain concatenation is safe here.
        query += ' LIMIT ' + maxRows;

        // --- Execute with user mode (defense in depth: sharing + FLS enforced) ----
        try {
            return Database.queryWithBinds(query, bindValues, AccessLevel.USER_MODE);
        } catch (Exception e) {
            throw new SearchException('Query failed: ' + e.getMessage());
        }
    }

    /**
     * Resolves the object (case-insensitively) and verifies the running user
     * has read access to it.
     */
    private static Schema.DescribeSObjectResult describeAccessibleObject(String objectApiName) {
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }
        String target = objectApiName.trim().toLowerCase();
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType resolvedType = null;
        for (String key : globalDescribe.keySet()) {
            if (key.toLowerCase() == target) {
                resolvedType = globalDescribe.get(key);
                break;
            }
        }
        if (resolvedType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }
        Schema.DescribeSObjectResult describeResult = resolvedType.getDescribe();
        if (!describeResult.isAccessible()) {
            throw new SearchException('No read access to object: ' + objectApiName);
        }
        return describeResult;
    }

    /**
     * Builds a case-insensitive lookup of field API name -> field token
     * for the given object.
     */
    private static Map<String, Schema.SObjectField> buildFieldMap(Schema.DescribeSObjectResult objectDescribe) {
        Map<String, Schema.SObjectField> fieldsByLowerName = new Map<String, Schema.SObjectField>();
        Map<String, Schema.SObjectField> describeFields = objectDescribe.fields.getMap();
        for (String key : describeFields.keySet()) {
            fieldsByLowerName.put(key.toLowerCase(), describeFields.get(key));
        }
        return fieldsByLowerName;
    }
