@isTest
private class AddressVerificationServiceTest {

    private static final String ENDPOINT = 'callout:FB_Address_API/v2/verify';
    private static final String CONTENT_TYPE = 'application/json';

    private static Account testAccount() {
        return new Account(
            Name = 'Test Account',
            BillingStreet = '123 Main St',
            BillingCity = 'Springfield',
            BillingPostalCode = '12345',
            BillingCountry = 'US'
        );
    }

    /**
     * Mock that returns a configured status code / body and records the request it
     * received so tests can assert against the documented API contract.
     */
    private class ConfigurableMock implements HttpCalloutMock {
        private Integer statusCode;
        private String responseBody;

        public String capturedMethod;
        public String capturedEndpoint;
        public String capturedContentType;
        public String capturedBody;

        public ConfigurableMock(Integer statusCode, String responseBody) {
            this.statusCode = statusCode;
            this.responseBody = responseBody;
        }

        public HttpResponse respond(HttpRequest req) {
            capturedMethod = req.getMethod();
            capturedEndpoint = req.getEndpoint();
            capturedContentType = req.getHeader('Content-Type');
            capturedBody = req.getBody();

            HttpResponse res = new HttpResponse();
            res.setStatusCode(statusCode);
            res.setBody(responseBody);
            res.setHeader('Content-Type', 'application/json');
            return res;
        }
    }

    /**
     * Mock used to prove that no callout is made: if the service does attempt a
     * callout, respond() fails the test.
     */
    private class FailIfCalledMock implements HttpCalloutMock {
        public HttpResponse respond(HttpRequest req) {
            Assert.fail('Expected no callout to be made, but a callout was attempted to: '
                + req.getEndpoint());
            return null;
        }
    }

    @isTest
    static void blankBillingStreetIsSkippedWithoutCallout() {
        Account acct = testAccount();
        acct.BillingStreet = '   '; // blank per String.isBlank, incl. whitespace-only

        Test.setMock(HttpCalloutMock.class, new FailIfCalledMock());

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        Assert.areEqual('SKIPPED', result.status, 'Blank street must yield SKIPPED');
        Assert.areEqual(false, result.changed, 'SKIPPED result must not be marked changed');
    }

    @isTest
    static void requestMatchesApiContract() {
        Account acct = testAccount();
        ConfigurableMock mock = new ConfigurableMock(200, '{"status":"VERIFIED"}');
        Test.setMock(HttpCalloutMock.class, mock);

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        Assert.areEqual('POST', mock.capturedMethod, 'Request method must be POST');
        Assert.areEqual(ENDPOINT, mock.capturedEndpoint, 'Request endpoint must match the API contract');
        Assert.areEqual(CONTENT_TYPE, mock.capturedContentType, 'Content-Type header must be application/json');

        Map<String, Object> sent = (Map<String, Object>) JSON.deserializeUntyped(mock.capturedBody);
        Assert.areEqual('123 Main St', (String) sent.get('street'), 'Body street must come from BillingStreet');
        Assert.areEqual('Springfield', (String) sent.get('city'), 'Body city must come from BillingCity');
        Assert.areEqual('12345', (String) sent.get('postalCode'), 'Body postalCode must come from BillingPostalCode');
        Assert.areEqual('US', (String) sent.get('country'), 'Body country must come from BillingCountry');
        Assert.areEqual(4, sent.size(), 'Body must contain exactly the four documented keys');

        Assert.areEqual('VERIFIED', result.status);
        Assert.areEqual(false, result.changed);
    }

    @isTest
    static void calloutIsMadeEvenWhenOtherBillingFieldsAreBlank() {
        // Street is populated, so a callout must happen regardless of the other fields.
        // Catches mutations that skip on the wrong (blank) field.
        Account acct = testAccount();
        acct.BillingCity = null;
        acct.BillingPostalCode = null;
        acct.BillingCountry = null;

        ConfigurableMock mock = new ConfigurableMock(200, '{"status":"VERIFIED"}');
        Test.setMock(HttpCalloutMock.class, mock);

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        Assert.areEqual('VERIFIED', result.status, 'Populated street must result in a callout, not SKIPPED');

        Map<String, Object> sent = (Map<String, Object>) JSON.deserializeUntyped(mock.capturedBody);
        Assert.areEqual('123 Main St', (String) sent.get('street'));
        Assert.areEqual(null, (String) sent.get('city'));
        Assert.areEqual(null, (String) sent.get('postalCode'));
        Assert.areEqual(null, (String) sent.get('country'));
    }

    @isTest
    static void non200StatusThrowsAddressVerificationExceptionWithStatusCode() {
        // 201 catches mutations like "!= 200" becoming "> 200" or ">= 300".
        // 400 and 500 catch off-by-one / inverted comparisons.
        for (Integer code : new List<Integer>{ 201, 400, 500 }) {
            Account acct = testAccount();
            Test.setMock(HttpCalloutMock.class, new ConfigurableMock(code, '{"status":"VERIFIED"}'));

            try {
                AddressVerificationService.verify(acct);
                Assert.fail('Expected AddressVerificationException for HTTP ' + code);
            } catch (AddressVerificationService.AddressVerificationException e) {
                Assert.isTrue(e.getMessage().contains(String.valueOf(code)),
                    'Exception message must contain the status code ' + code
                    + ' but was: ' + e.getMessage());
            }
        }
    }

    @isTest
    static void verifiedAndInvalidResponsesLeaveAccountUntouched() {
        // The response includes an address on purpose: if the service wrongly treats
        // VERIFIED or INVALID as CORRECTED, the account fields (or changed flag) give it away.
        for (String status : new List<String>{ 'VERIFIED', 'INVALID' }) {
            Account acct = testAccount();
            Test.setMock(HttpCalloutMock.class, new ConfigurableMock(200,
                '{"status":"' + status + '","address":{"street":"X","city":"Y","postalCode":"Z","country":"W"}}'));

            AddressVerificationService.Result result = AddressVerificationService.verify(acct);

            Assert.areEqual(status, result.status, 'Result status must be the response status');
            Assert.areEqual(false, result.changed, status + ' must not mark the result as changed');
            Assert.areEqual('123 Main St', acct.BillingStreet, status + ' must not overwrite BillingStreet');
            Assert.areEqual('Springfield', acct.BillingCity, status + ' must not overwrite BillingCity');
            Assert.areEqual('12345', acct.BillingPostalCode, status + ' must not overwrite BillingPostalCode');
            Assert.areEqual('US', acct.BillingCountry, status + ' must not overwrite BillingCountry');
        }
    }

    @isTest
    static void correctedResponseOverwritesAllFourBillingFields() {
        Account acct = testAccount();
        Test.setMock(HttpCalloutMock.class, new ConfigurableMock(200,
            '{"status":"CORRECTED","address":{"street":"1 New St","city":"New City",'
            + '"postalCode":"99999","country":"CA"}}'));

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        Assert.areEqual('CORRECTED', result.status);
        Assert.areEqual(true, result.changed, 'CORRECTED must mark result.changed as true');
        Assert.areEqual('1 New St', acct.BillingStreet, 'BillingStreet must be overwritten by corrected street');
        Assert.areEqual('New City', acct.BillingCity, 'BillingCity must be overwritten by corrected city');
        Assert.areEqual('99999', acct.BillingPostalCode, 'BillingPostalCode must be overwritten by corrected postalCode');
        Assert.areEqual('CA', acct.BillingCountry, 'BillingCountry must be overwritten by corrected country');
    }
}
