public inherited sharing class ErpSyncFinalizer implements Finalizer {
    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(FinalizerContext context) {
        Exception jobException = context.getException();

        FB_Job_Log__c jobLog = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Attempt__c  = attempt
        );

        if (jobException == null) {
            jobLog.Status__c = 'Success';
        } else {
            jobLog.Status__c = 'Failed';
            String errorMessage = jobException.getMessage();
            jobLog.Error__c = errorMessage != null ? errorMessage.left(255) : 'Unknown error';

            // Retry up to a maximum of 3 attempts (first run is attempt 1,
            // so retries are enqueued for attempts 2 and 3 only).
            if (attempt < 3) {
                System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
            }
        }

        insert jobLog;
    }
}
