public inherited sharing class LogPurgeJob implements Schedulable {

    private static final Integer INFO_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;
    private static final String NIGHTLY_JOB_NAME = 'Log purge (nightly)';
    private static final String NIGHTLY_CRON = '0 0 2 * * ?';

    // No-argument constructor required for scheduling.
    public LogPurgeJob() {
    }

    public void execute(SchedulableContext ctx) {
        deleteExpiredLogs();
    }

    public static Id scheduleNightly() {
        return System.schedule(NIGHTLY_JOB_NAME, NIGHTLY_CRON, new LogPurgeJob());
    }

    private static void deleteExpiredLogs() {
        // Delete non-ERROR logs older than 30 days and ERROR logs older than 180 days.
        // A blank Level__c is treated as non-ERROR (i.e. purged after 30 days).
        Set<Id> logIdsToDelete = new Set<Id>();

        for (List<FB_Integration_Log__c> logs : [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (CreatedDate < LAST_N_DAYS:30 AND (Level__c = null OR Level__c != 'ERROR'))
                   OR (CreatedDate < LAST_N_DAYS:180 AND Level__c = 'ERROR')
        ]) {
            for (FB_Integration_Log__c log : logs) {
                logIdsToDelete.add(log.Id);
            }
        }

        if (!logIdsToDelete.isEmpty()) {
            // One bulk DML for all records; partial success so a single row
            // failure (e.g. lock contention) does not roll back the whole purge.
            Database.delete(new List<Id>(logIdsToDelete), false);
        }
    }
}
