public inherited sharing class Opportunities extends fflib_SObjectDomain
{
    /**
     * @description Number of days added to today when defaulting CloseDate.
     */
    private static final Integer DEFAULT_CLOSE_DATE_OFFSET_DAYS = 30;

    /**
     * @description Value used when an Opportunity is created without a Type.
     */
    private static final String DEFAULT_TYPE = 'New Customer';

    /**
     * @description Constructs the domain for the given records.
     * @param opportunities List of Opportunity records being processed.
     */
    public Opportunities(List<Opportunity> opportunities)
    {
        super(opportunities);
    }

    /**
     * @description Standard inner class required by fflib_SObjectDomain
     *              so the library can construct this domain via
     *              Application.Domain(Opportunity.class) and, most
     *              importantly, via triggerHandler.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }
    }

    /**
     * @description Entry point invoked by the trigger handler for before
     *              insert. Applies default field values to records where
     *              the user has not supplied them.
     */
    public override void onBeforeInsert()
    {
        applyDefaults();
    }

    /**
     * @description Defaults CloseDate and Type for any record where those
     *              values are blank. Values already set are preserved.
     */
    private void applyDefaults()
    {
        Date defaultCloseDate = Date.today().addDays(DEFAULT_CLOSE_DATE_OFFSET_DAYS);

        for (Opportunity opportunity : (List<Opportunity>) Records)
        {
            if (opportunity.CloseDate == null)
            {
                opportunity.CloseDate = defaultCloseDate;
            }

            if (opportunity.Type == null)
            {
                opportunity.Type = DEFAULT_TYPE;
            }
        }
    }
