public inherited sharing class OpportunitiesSelector extends fflib_SObjectSelector {
    public Schema.SObjectType getSObjectType() {
        return Opportunity.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Opportunity.Id,
            Opportunity.Name,
            Opportunity.AccountId,
            Opportunity.StageName,
            Opportunity.Amount,
            Opportunity.CloseDate
        };
    }

    public List<Opportunity> selectById(Set<Id> opportunityIds) {
        return (List<Opportunity>) selectSObjectsById(opportunityIds);
    }

    /**
     * Returns the open opportunities of the given accounts, highest Amount first,
     * opportunities without an Amount last, ties broken by earliest CloseDate.
     * At most maxRecords rows are returned in a single query.
     * The query is built from the selector's query factory, so the selector's
     * field list and CRUD/FLS settings keep applying. The parent Account's Name
     * is included via a cross-object field, registered with assertSObjectField
     * so that FLS is still enforced on Account.Name.
     */
    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        // Guard clauses keep the query bulk-safe and avoid a pointless round trip.
        if (accountIds == null || accountIds.isEmpty() || maxRecords == null || maxRecords <= 0) {
            return new List<Opportunity>();
        }

        fflib_QueryFactory queryFactory = newQueryFactory()
            // Declare the cross-object field so the selector's FLS enforcement
            // covers Account.Name as well.
            .assertSObjectField(Schema.Account.SObjectType, Schema.Account.Name)
            .addField('Account.Name')
            .setCondition('AccountId IN :accountIds AND IsClosed = false')
            .setSortOrder('Amount DESC NULLS LAST, CloseDate ASC')
            .setLimit(maxRecords);

        return (List<Opportunity>) query(queryFactory);
    }
}
