public inherited sharing class CaseEscalationService {

    public class EscalationException extends Exception {}

    public static void escalate(Set<Id> caseIds, String reason) {
        // Validate the reason first, before any reads or writes.
        if (String.isBlank(reason)) {
            throw new EscalationException('An escalation reason is required.');
        }

        // Nothing to do for null or empty case id sets.
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        // Retrieve the cases through the (mockable) selector factory.
        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);

        // Single unit of work for all writes in this transaction.
        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        Boolean hasChanges = false;

        for (Case c : cases) {
            // Skip closed or already-escalated cases.
            if (c.Status == 'Closed' || c.IsEscalated == true) {
                continue;
            }

            // Escalate the case.
            c.IsEscalated = true;
            c.Priority = 'High';
            uow.registerDirty(c);

            // Create the follow-up task owned by the case owner.
            Task escalationTask = new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = c.Id,
                OwnerId = c.OwnerId,
                ActivityDate = Date.today().addDays(1),
                Priority = 'High'
            );
            uow.registerNew(escalationTask);

            hasChanges = true;
        }

        // Only commit when at least one case was escalated.
        if (hasChanges) {
            uow.commitWork();
        }
    }
}
