public with sharing class CasePriorityHandler {

    /**
     * Sets Case Priority to 'High' when the related Account has Rating = 'Hot'.
     * Cases with no Account, or whose Account is not 'Hot', keep their original Priority.
     *
     * Note: This method is bulkified (one SOQL query for the whole batch) instead of
     * querying inside the loop, because the ERP integration inserts up to 200 cases
     * at once and a per-record query would exceed the 100-SOQL governor limit.
     */
    public static void setPriorityForHotAccounts(List<Case> newCases) {
        // Collect the AccountIds we actually need (skipping blanks).
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        // One query for the entire batch.
        Map<Id, Account> accountsById = new Map<Id, Account>(
            [
                SELECT Id, Rating
                FROM Account
                WHERE Id IN :accountIds
            ]
        );

        for (Case c : newCases) {
            if (c.AccountId != null) {
                Account acct = accountsById.get(c.AccountId);
                if (acct != null && acct.Rating == 'Hot') {
                    c.Priority = 'High';
                }
            }
            // No else branch: all other cases keep the Priority they arrived with.
        }
    }
}
