import { LightningElement, api } from 'lwc';
import { getRecord, getFieldDisplayValue } from 'lightning/uiRecordApi';

import NAME_FIELD from '@salesforce/schema/Account.Name';
import INDUSTRY_FIELD from '@salesforce/schema/Account.Industry';
import ANNUAL_REVENUE_FIELD from '@salesforce/schema/Account.AnnualRevenue';
import OWNER_NAME_FIELD from '@salesforce/schema/Account.Owner.Name';

const FIELDS = [NAME_FIELD];
const OPTIONAL_FIELDS = [INDUSTRY_FIELD, ANNUAL_REVENUE_FIELD, OWNER_NAME_FIELD];

export default class AccountHeader extends LightningElement {
    @api recordId;

    @wire(getRecord, {
        recordId: '$recordId',
        fields: FIELDS,
        optionalFields: OPTIONAL_FIELDS
    })
    wiredRecord;

    get record() {
        return this.wiredRecord?.data;
    }

    get error() {
        return this.wiredRecord?.error;
    }

    get isLoading() {
        return !this.record && !this.error;
    }

    get accountName() {
        return this.record?.fields?.Name?.value;
    }

    get industry() {
        return this.record?.fields?.Industry?.value;
    }

    get annualRevenue() {
        const field = this.record?.fields?.AnnualRevenue;
        if (!field) {
            return undefined;
        }
        // Use the display value when available (respects currency/locale),
        // falling back to the raw value formatted as a number.
        return field.value != null
            ? getFieldDisplayValue(this.record, ANNUAL_REVENUE_FIELD) ?? field.value
            : undefined;
    }

    get ownerName() {
        return this.record?.fields?.Owner?.displayValue ?? this.record?.fields?.Owner?.value?.fields?.Name?.value;
    }
}
