```javascript
import { LightningElement, api } from 'lwc';

export default class AccountContactList extends LightningElement {
    /**
     * The parent owns this array; this component performs no data fetching.
     * Each item is expected to look like { Id, Name, Title? }.
     */
    @api contacts;

    /**
     * True when the parent passed a non-empty array of contacts.
     * Defensive against undefined, null, or a non-array value.
     */
    get hasContacts() {
        return Array.isArray(this.contacts) && this.contacts.length > 0;
    }

    /**
     * A name-sorted copy of the incoming array. Sorting a shallow copy keeps
     * the parent-owned array unmutated, and the getter re-evaluates whenever
     * the parent passes a new array reference, so the list re-renders.
     */
    get sortedContacts() {
        if (!this.hasContacts) {
            return [];
        }
        return [...this.contacts].sort((a, b) =>
            String(a.Name ?? '').localeCompare(String(b.Name ?? ''))
        );
    }

    /**
     * "1 contact" for exactly one contact, "<n> contacts" otherwise.
     * Only rendered when hasContacts is true, so the zero case is unreachable
     * in the template.
     */
    get contactCountText() {
        const count = this.contacts.length;
        return count === 1 ? '1 contact' : `${count} contacts`;
    }
}
