    handleSearchChange(event) {
        this.searchTerm = event.target.value;
        this._clearDebounce();

        const trimmed = this.searchTerm.trim();
        if (trimmed.length < MIN_SEARCH_LENGTH) {
            // Cancel pending search, don't call Apex, clear results.
            this._latestRequestSeq++;
            this.results = [];
            this.error = undefined;
            return;
        }

        this._debounceTimeoutId = setTimeout(() => {
            this._performSearch(trimmed);
        }, DEBOUNCE_DELAY_MS);
    }

    _clearDebounce() {
        if (this._debounceTimeoutId) {
            clearTimeout(this._debounceTimeoutId);
            this._debounceTimeoutId = undefined;
        }
    }

    _performSearch(searchTerm) {
        if (!this._isConnected) {
            return;
        }

        const currentRequestSeq = ++this._latestRequestSeq;
        const requestId = currentRequestSeq;
        this._requestSeq = requestId;

        searchContacts({ searchTerm })
            .then((contacts) => {
                // Ignore stale responses and responses after disconnect.
                if (!this._isConnected || requestId !== this._requestSeq) {
                    return;
                }
                this.results = contacts ? [...contacts] : [];
                this.error = undefined;
            })
            .catch((error) => {
                if (!this._isConnected || requestId !== this._requestSeq) {
                    return;
                }
                this.results = [];
                this.error = error && error.body ? error.body.message : error;
            });
    }
}
