import { LightningElement, api } from 'lwc';
import FavoriteAdd from '@salesforce/label/c.Favorite_Add';
import FavoriteRemove from '@salesforce/label/c.Favorite_Remove';

/**
 * Icon-style toggle button that marks a record as a favorite.
 * The parent owns the source of truth via the public `favorite` property;
 * clicks optimistically flip the locally rendered state and notify the
 * parent through a `favoritechange` CustomEvent.
 */
export default class FavoriteToggle extends LightningElement {
    // Backing field for the public property. We deliberately do not assign
    // to the @api property itself (see @lwc/lwc/no-api-reassignments); the
    // setter keeps the local state in sync whenever the parent changes it.
    _favorite = false;

    @api
    get favorite() {
        return this._favorite;
    }
    set favorite(value) {
        this._favorite = value;
    }

    labels = {
        add: FavoriteAdd,
        remove: FavoriteRemove,
    };

    /**
     * Label of the action a click performs: when the record is currently a
     * favorite, clicking removes it; otherwise clicking adds it.
     */
    get actionLabel() {
        return this._favorite ? this.labels.remove : this.labels.add;
    }

    /**
     * `aria-pressed` must be the string "true" or "false".
     */
    get ariaPressed() {
        return this._favorite ? 'true' : 'false';
    }

    get starFill() {
        return this._favorite ? '#ffb00d' : 'none';
    }

    get starStroke() {
        return this._favorite ? 'none' : 'currentColor';
    }

    /**
     * Optimistic UI: flip the rendered state immediately, then let the
     * parent know so it can persist (and, if needed, correct) the value.
     *
     * @param {Event} event
     */
    handleClick() {
        this._favorite = !this._favorite;
        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: {
                    favorite: this._favorite,
                },
            }),
        );
    }
}
