import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    /** Array of { key, productName, quantity } */
    @api lines = [];

    showError = false;

    get lineEditors() {
        return Array.from(this.template.querySelectorAll('c-line-item-editor'));
    }

    handleAction(event) {
        const action = event.currentTarget.dataset.action;
        if (action === 'reset') {
            this.handleReset();
        } else if (action === 'submit') {
            this.handleSubmit();
        }
    }

    handleReset() {
        this.lineEditors.forEach((editor) => editor.reset());
        this.showError = false;
    }

    handleSubmit() {
        // Validate every editor, even after one fails, so all errors show at once.
        const allValid = this.lineEditors.reduce(
            (valid, editor) => editor.validate() && valid,
            true
        );

        if (!allValid) {
            this.showError = true;
            return;
        }

        // getValue() results, in display order.
        const lines = this.lineEditors.map((editor) => editor.getValue());

        this.showError = false;
        this.dispatchEvent(
            new CustomEvent('submit', {
                detail: { lines },
            })
        );
    }
}
