import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60 * 1000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    error;
    isLoaded = false;

    _pollingTimer;
    _inFlight = false;

    connectedCallback() {
        // Load immediately on insert, then poll every 60 seconds.
        this.loadStats();
        this._pollingTimer = setInterval(() => {
            this.loadStats();
        }, REFRESH_INTERVAL_MS);

        // Pause polling while the tab is hidden; refresh immediately on return.
        document.addEventListener('visibilitychange', this.handleVisibilityChange);
    }

    disconnectedCallback() {
        // Stop all polling and clean up the document listener.
        if (this._pollingTimer) {
            clearInterval(this._pollingTimer);
            this._pollingTimer = undefined;
        }
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    }

    handleVisibilityChange = () => {
        if (document.visibilityState === 'visible') {
            // Load immediately when the agent returns to the tab.
            this.loadStats();
        }
        // While hidden, the interval keeps ticking but loadStats() skips,
        // so no requests are made in background tabs.
    };

    loadStats() {
        // Never overlap requests and never run while the tab is hidden.
        if (this._inFlight || document.visibilityState === 'hidden' || !this.isConnected) {
            return;
        }

        this._inFlight = true;
        getQueueStats()
            .then((stats) => {
                this._inFlight = false;
                if (!this.isConnected) {
                    return;
                }
                if (stats) {
                    this.waiting = stats.waiting;
                    this.longestWaitMinutes = stats.longestWaitMinutes;
                    this.isLoaded = true;
                    // A successful refresh clears any previous error.
                    this.error = undefined;
                }
            })
            .catch((err) => {
                this._inFlight = false;
                if (!this.isConnected) {
                    return;
                }
                // Show the error but keep polling; the next success clears it.
                this.error = err;
            });
    }
}
