import { LightningElement, api } from 'lwc';

/**
 * Single-select listbox following the WAI-ARIA listbox pattern.
 * DOM focus stays on the <ul role="listbox">; the active option is only
 * referenced via aria-activedescendant.
 */
let uidCounter = 0;

export default class StatusListbox extends LightningElement {
    /** Accessible name of the list (used as aria-label). */
    @api label = '';

    /** Array of { value, label }. */
    @api options = [];

    _value;
    activeIndex = 0;
    _listboxId;

    constructor() {
        super();
        // Unique per instance so option ids never collide across components.
        this._listboxId = `statuslistbox-${++uidCounter}`;
    }

    @api
    get value() {
        return this._value;
    }

    set value(newValue) {
        this._value = newValue;
        // The parent may change the value at any time; the active option
        // must then move to the newly selected option.
        this.syncActiveToValue();
    }

    connectedCallback() {
        // Initial active option: the selected option, or the first option
        // if nothing is selected.
        this.activeIndex = Math.max(this.selectedIndex, 0);
    }

    get selectedIndex() {
        return this.options.findIndex(
            (option) => option.value === this._value,
        );
    }

    syncActiveToValue() {
        const index = this.selectedIndex;
        if (index !== -1) {
            this.activeIndex = index;
        }
    }

    optionId(index) {
        return `${this._listboxId}-option-${index}`;
    }

    get activeId() {
        return this.optionId(this.activeIndex);
    }

    get renderedOptions() {
        return this.options.map((option, index) => ({
            ...option,
            id: this.optionId(index),
            selected: option.value === this._value ? 'true' : 'false',
        }));
    }

    handleKeydown(event) {
        if (this.options.length === 0) {
            return;
        }
        const lastIndex = this.options.length - 1;

        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                this.activeIndex = Math.min(this.activeIndex + 1, lastIndex);
                break;
            case 'ArrowUp':
                event.preventDefault();
                this.activeIndex = Math.max(this.activeIndex - 1, 0);
                break;
            case 'Home':
                event.preventDefault();
                this.activeIndex = 0;
                break;
            case 'End':
                event.preventDefault();
                this.activeIndex = lastIndex;
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this.selectIndex(this.activeIndex);
                break;
            default:
                // All other keys (including Tab) keep default behaviour.
                break;
        }
    }

    handleOptionClick(event) {
        const clickedValue = event.currentTarget.dataset.value;
        const index = this.options.findIndex(
            (option) => String(option.value) === clickedValue,
        );
        if (index === -1) {
            return;
        }
        // Clicking an option both makes it active and selects it.
        this.activeIndex = index;
        this.selectIndex(index);
    }

    selectIndex(index) {
        const option = this.options[index];
        if (!option || option.value === this._value) {
            // No option, or it was already selected: nothing to dispatch.
            return;
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value },
            }),
        );
    }
}
