import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    /**
     * Public heading. Stored as-is (never mutated) so the parent's value
     * stays intact and later changes are reflected; upper-casing for
     * display is done by the headingDisplay getter.
     */
    @api heading = '';

    get headingDisplay() {
        return this.heading ? this.heading.toUpperCase() : '';
    }

    /**
     * Public tasks. The component never mutates the parent's array or task
     * objects: it always works on its own copies. Passing a new array
     * replaces the current list with a copy of it.
     */
    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        this._tasks = Array.isArray(value) ? value : [];
        this.items = this.copyTasks(this._tasks);
    }

    copyTasks(tasks) {
        return tasks.map((task) => ({ ...task }));
    }

    connectedCallback() {
        // tasks may have been provided as a property before connect;
        // make sure we are working on our own copies.
        this.items = this.copyTasks(this._tasks);
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return;
        }

        let id = `new-${this.nextId++}`;
        while (this.items.some((task) => task.id === id)) {
            id = `new-${this.nextId++}`;
        }

        // Immutable update: new array, new task objects -> safe reactivity.
        this.items = [...this.items, { id, label, done: false }];
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
        this.newLabel = '';
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        this.items = this.items.map((task) =>
            task.id === id ? { ...task, done: !task.done } : task
        );
    }
}
