/**
 * @description Service that accepts one-off website gifts and routes them through
 *              NPSP's Data Import engine (BDI) instead of inserting Contacts and
 *              Opportunities directly. Each gift is staged as one npsp__Data_Import__c
 *              record (which remains in the org as the audit trail), processed
 *              synchronously in the same transaction via npsp.BDI_API, so NPSP's
 *              contact matching, household creation and donation processing rules
 *              (from the org's npsp__Data_Import_Settings__c hierarchy custom setting)
 *              all apply.
 */
public inherited sharing class GiftImportService {

    private static final String DONOR_CONTACT1 = 'Contact1';
    private static final String STATUS_IMPORTED = 'Imported';

    /**
     * @description A one-off gift received from the website.
     */
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    /**
     * @description Outcome of importing a single gift.
     */
    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /**
     * @description Stages one NPSP Data Import record per gift and processes all of them
     *              synchronously, in the same transaction, through NPSP's data import API.
     *              Returns one ImportResult per gift, in input order. Rows NPSP rejects
     *              are reported individually and do not stop the other rows.
     * @param gifts the gifts received from the website; null or empty returns an empty list
     * @return list of ImportResult, one per input gift, in input order
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // 1. Stage one NPSP Data Import record per gift (kept in the org as the audit trail).
        List<npsp__Data_Import__c> stagedImports = new List<npsp__Data_Import__c>();
        for (WebGift gift : gifts) {
            stagedImports.add(toDataImport(gift));
        }
        insert stagedImports;

        // 2. Process all staged rows synchronously, in this transaction, using NPSP's
        //    Apex data import API. With the org's Data Import settings, NPSP matches
        //    contacts on first name + last name + email, creates households as needed,
        //    and never matches existing donations. Row-level failures are captured by
        //    NPSP on the Data Import record (npsp__Status__c = 'Failed' plus
        //    npsp__FailureInformation__c) and do not throw or abort the run.
        List<Id> stagedIds = new List<Id>();
        for (npsp__Data_Import__c di : stagedImports) {
            stagedIds.add(di.Id);
        }
        npsp.BDI_API.runDataImport(stagedIds);

        // 3. Re-query the staged records to read back NPSP's results, and build one
        //    result per input gift, in input order.
        Map<Id, npsp__Data_Import__c> processedById = new Map<Id, npsp__Data_Import__c>(
            [SELECT Id,
                    npsp__Status__c,
                    npsp__Contact1Imported__c,
                    npsp__DonationImported__c,
                    npsp__FailureInformation__c
             FROM npsp__Data_Import__c
             WHERE Id IN :stagedIds]
        );

        for (npsp__Data_Import__c stagedDi : stagedImports) {
            results.add(toResult(processedById.get(stagedDi.Id)));
        }

        return results;
    }

    /**
     * @description Maps a website gift to a single NPSP Data Import staging record.
     *              A null WebGift still stages a record so NPSP records the failure
     *              information against it, preserving the audit trail.
     * @param gift the gift to stage
     * @return an unsaved npsp__Data_Import__c record
     */
    private static npsp__Data_Import__c toDataImport(WebGift gift) {
        npsp__Data_Import__c di = new npsp__Data_Import__c();

        if (gift != null) {
            di.npsp__Contact1_Firstname__c = gift.firstName;
            di.npsp__Contact1_Lastname__c = gift.lastName;
            di.npsp__Contact1_Personal_Email__c = gift.email;
            di.npsp__Donation_Amount__c = gift.amount;
            di.npsp__Donation_Date__c = gift.giftDate;
        }

        // The gift is a personal donation from an individual, so the donor is Contact1;
        // NPSP will create the Household Account for a new donor per its settings.
        di.npsp__Donation_Donor__c = DONOR_CONTACT1;

        return di;
    }

    /**
     * @description Builds the public result for one gift from the processed
     *              NPSP Data Import record.
     * @param di the processed NPSP Data Import record (may be null if it was never processed)
     * @return the ImportResult for that gift
     */
    private static ImportResult toResult(npsp__Data_Import__c di) {
        ImportResult result = new ImportResult();

        if (di == null) {
            result.success = false;
            result.errorMessage = 'NPSP Data Import record could not be processed.';
            return result;
        }

        result.success = di.npsp__Status__c != null
            && STATUS_IMPORTED.equalsIgnoreCase(di.npsp__Status__c);
        result.contactId = di.npsp__Contact1Imported__c;
        result.opportunityId = di.npsp__DonationImported__c;

        if (!result.success) {
            result.errorMessage = di.npsp__FailureInformation__c != null
                ? di.npsp__FailureInformation__c
                : 'NPSP import failed with status: ' + di.npsp__Status__c;
        }

        return result;
    }
}
