/**
 * @description Creates/replaces GAU Allocations on an Opportunity based on a
 * percentage split keyed by General Accounting Unit Id.
 *
 * Design notes:
 * - Every percentage passed in is also persisted on npsp__Percent__c. NPSP
 *   recalculates npsp__Amount__c from npsp__Percent__c whenever the parent
 *   Opportunity Amount changes, so a corrected $1,000 gift split 60/40 that is
 *   later changed to $2,000 will automatically show allocations of $1,200 and
 *   $800 with no further code required.
 * - All input validation happens up front, before any DML, so the org data is
 *   never left in a partially updated state. The delete + insert pair is also
 *   wrapped in a savepoint for full atomicity.
 * - No DML inside loops; the whole operation is two bulk statements regardless
 *   of how many funds are in the split.
 */
public inherited sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    private static final Integer MAX_PERCENT = 100;

    /**
     * @description Replaces all existing GAU Allocations on the Opportunity with
     *              one Allocation per entry in percentByGauId.
     * @param opportunityId  the Opportunity whose allocations to replace.
     * @param percentByGauId map of npsp__General_Accounting_Unit__c Id to
     *                       percentage (60 means 60%). Totals below 100% are
     *                       allowed; the remainder stays unallocated.
     * @return the newly inserted npsp__Allocation__c records.
     * @throws GauAllocationService.AllocationException if any input is invalid,
     *         the Opportunity does not exist, or the DML could not be completed.
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        validateInputs(opportunityId, percentByGauId);

        // --- Validate GAUs exist and are active (read-only, no DML yet) ---
        Map<Id, npsp__General_Accounting_Unit__c> gausById = new Map<Id, npsp__General_Accounting_Unit__c>(
            [SELECT Id, Name, npsp__Active__c
             FROM npsp__General_Accounting_Unit__c
             WHERE Id IN :percentByGauId.keySet()]
        );
        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gausById.get(gauId);
            if (gau == null) {
                throw new AllocationException(
                    'General Accounting Unit not found: ' + gauId
                );
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException(
                    'General Accounting Unit "' + gau.Name + '" (' + gauId + ') is inactive.'
                );
            }
        }

        // --- Validate the Opportunity exists and has an amount to split ---
        List<Opportunity> opps = [
            SELECT Id, Amount
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];
        if (opps.isEmpty()) {
            throw new AllocationException('Opportunity not found: ' + opportunityId);
        }
        Decimal opportunityAmount = opps[0].Amount == null ? 0 : opps[0].Amount;

        // --- Build the new allocations ---
        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            Decimal percent = percentByGauId.get(gauId);
            newAllocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percent,
                npsp__Amount__c = (opportunityAmount * percent) / 100
            ));
        }

        // --- Replace existing allocations atomically ---
        Savepoint beforeChanges = Database.setSavepoint();
        try {
            List<npsp__Allocation__c> existingAllocations = [
                SELECT Id
                FROM npsp__Allocation__c
                WHERE npsp__Opportunity__c = :opportunityId
            ];
            if (!existingAllocations.isEmpty()) {
                delete existingAllocations;
            }

            insert newAllocations;

            return newAllocations;
        } catch (Exception e) {
            Database.rollback(beforeChanges);
            throw new AllocationException(
                'Unable to replace GAU Allocations for Opportunity ' + opportunityId + ': ' + e.getMessage()
            );
        }
    }

    /**
     * @description Validates the method arguments before any data is touched.
     * @throws GauAllocationService.AllocationException on any invalid input.
     */
    private static void validateInputs(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id must not be null.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException(
                'The percentage map must not be null or empty; provide at least one GAU allocation.'
            );
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            Decimal percent = percentByGauId.get(gauId);
            if (percent == null) {
                throw new AllocationException(
                    'Percentage must not be null for GAU ' + gauId + '.'
                );
            }
            if (percent <= 0) {
                throw new AllocationException(
                    'Percentage must be greater than 0 for GAU ' + gauId + ' (received: ' + percent + ').'
                );
            }
            totalPercent += percent;
        }

        if (totalPercent > MAX_PERCENT) {
            throw new AllocationException(
                'Percentages total ' + totalPercent + '%, which exceeds the maximum of ' + MAX_PERCENT +
                '%. Totals below 100% are allowed, but not above.'
            );
        }
    }
}
