/**
 * @description Turns an open NPSP donation (pledge) with Payments enabled into a
 *              monthly installment plan.
 *
 *              Paid and written-off payments are treated as history and left
 *              untouched. All other payments are deleted and replaced by
 *              `numberOfPayments` new unpaid payments, scheduled monthly from
 *              `firstPaymentDate`. The last installment absorbs any rounding
 *              remainder so the installments add up exactly to the outstanding
 *              amount (opportunity Amount minus paid/written-off payments).
 *
 *              All validation happens before any DML, so a validation failure
 *              leaves the data completely untouched.
 */
public with sharing class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    /** Currency fields in this org carry two decimal places. */
    private static final Integer CURRENCY_SCALE = 2;

    /**
     * @description Splits the outstanding amount of an open opportunity into
     *              equal monthly installments.
     * @param  opportunityId    Id of the (open) Opportunity to schedule.
     * @param  numberOfPayments Number of installments to create (>= 1).
     * @param  firstPaymentDate Scheduled date of the first installment; each
     *                          subsequent installment is one month later.
     * @return The inserted payments, in schedule order.
     * @throws PaymentPlanService.PaymentPlanException if the inputs are invalid,
     *         the opportunity is closed (or does not exist), or the outstanding
     *         amount is not greater than zero. Nothing is changed in that case.
     */
    @AuraEnabled
    public static List<npe01__OppPayment__c> scheduleInstallments(Id opportunityId, Integer numberOfPayments, Date firstPaymentDate) {
        // ------------------------------------------------------------------
        // 1. Input validation (no DML has happened yet)
        // ------------------------------------------------------------------
        if (opportunityId == null) {
            throw new PaymentPlanException('Opportunity Id is required.');
        }
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('Number of payments must be at least 1.');
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('First payment date is required.');
        }

        // ------------------------------------------------------------------
        // 2. Opportunity validation
        // ------------------------------------------------------------------
        List<Opportunity> opportunities = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
        ];
        if (opportunities.isEmpty()) {
            throw new PaymentPlanException('Opportunity not found: ' + opportunityId);
        }
        Opportunity opportunity = opportunities[0];
        if (opportunity.IsClosed) {
            throw new PaymentPlanException('Cannot schedule installments on a closed opportunity.');
        }

        // ------------------------------------------------------------------
        // 3. Split existing payments into history vs. removable, and compute
        //    the outstanding amount from the historical (paid / written-off)
        //    payments only.
        // ------------------------------------------------------------------
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();
        Decimal outstanding = (opportunity.Amount == null) ? 0 : opportunity.Amount;

        for (npe01__OppPayment__c payment : [
            SELECT Id, npe01__Paid__c, npe01__Written_Off__c, npe01__Payment_Amount__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ]) {
            if (payment.npe01__Paid__c == true || payment.npe01__Written_Off__c == true) {
                // History: keep it and subtract its amount from the outstanding total.
                outstanding -= (payment.npe01__Payment_Amount__c == null)
                    ? 0
                    : payment.npe01__Payment_Amount__c;
            } else {
                // Unpaid and not written off: will be deleted and replaced.
                paymentsToDelete.add(payment);
            }
        }

        // ------------------------------------------------------------------
        // 4. Outstanding amount validation (still no DML has happened)
        // ------------------------------------------------------------------
        if (outstanding <= 0) {
            throw new PaymentPlanException('Outstanding amount must be greater than zero.');
        }

        // ------------------------------------------------------------------
        // 5. Build the installments.
        //    Each installment is the outstanding amount divided by the number
        //    of payments, rounded DOWN to the cent. The last installment
        //    absorbs the remainder so the total matches exactly.
        // ------------------------------------------------------------------
        Decimal perInstallment = outstanding.divide(numberOfPayments, CURRENCY_SCALE, RoundingMode.DOWN);
        Decimal remainder = outstanding - (perInstallment * numberOfPayments);

        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal amount = perInstallment;
            if (i == numberOfPayments - 1) {
                amount += remainder;
            }
            newPayments.add(new npe01__OppPayment__c(
                npe01__Opportunity__c   = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Paid__c           = false,
                npe01__Written_Off__c    = false
            ));
        }

        // ------------------------------------------------------------------
        // 6. DML: remove the stale unpaid payments, then insert the plan.
        // ------------------------------------------------------------------
        if (!paymentsToDelete.isEmpty()) {
            delete paymentsToDelete;
        }
        insert newPayments;

        // `insert` preserves list order and populates the Ids, so this is the
        // inserted payments in schedule order.
        return newPayments;
    }
}
