/**
 * FamilyService
 *
 * Imports parent/child family links from an external student system into NPSP
 * Relationships (npe4__Relationship__c).
 *
 * Design notes
 * ------------
 * - The org uses the default NPSP "List Setting" reciprocal method. With that
 *   method the NPSP Relationship trigger automatically creates the reciprocal
 *   record on insert, resolving the type through the configured
 *   Relationship Lookup (npe4__Relationship_Lookup__c). The lookup row for
 *   `Parent` is Male: `Son`, Female: `Daughter`, Neutral: `Child`, so NPSP will
 *   show the child on the parent's record as Son / Daughter / Child based on
 *   the child's gender.
 * - Therefore we only insert ONE relationship per pair, oriented
 *   child -> parent with Type `Parent` and Status `Current`. NPSP creates the
 *   reciprocal (parent -> child) itself, guaranteeing exactly one record in
 *   each direction without duplicates or manual gender logic.
 * - Idempotency: before inserting we query existing relationships for all
 *   involved contacts and skip any pair that already has a relationship in
 *   either direction, so the import can be re-run safely.
 * - Bulk safety: one SOQL query and one DML statement total, regardless of the
 *   number of pairs (well within the 200-pair / 1-query / 1-DML limit).
 */
public with sharing class FamilyService {

    private static final String TYPE_PARENT = 'Parent';
    private static final String STATUS_CURRENT = 'Current';

    /**
     * Links each parent to their child as an NPSP Relationship.
     *
     * @param parentIdByChildId map of child Contact Id -> parent Contact Id.
     *        Null/empty input does nothing. Null entries and self-pairs are
     *        skipped. Pairs that already have a relationship (either direction)
     *        are skipped.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        // Null or empty input does nothing.
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Normalize input: drop null Ids and self-pairs (child == parent).
        Map<Id, Id> validPairs = new Map<Id, Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            validPairs.put(childId, parentId);
        }
        if (validPairs.isEmpty()) {
            return;
        }

        // Single SOQL query: all existing relationships touching any contact
        // involved in the import, so pairs can be skipped in either direction.
        Set<Id> contactIds = new Set<Id>();
        contactIds.addAll(validPairs.keySet());
        contactIds.addAll(validPairs.values());

        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
               OR npe4__RelatedContact__c IN :contactIds
        ]) {
            if (rel.npe4__Contact__c == null || rel.npe4__RelatedContact__c == null) {
                continue;
            }
            // Store the pair in both orientations so either-direction matches
            // are found with a simple Set lookup.
            existingPairKeys.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
            existingPairKeys.add(pairKey(rel.npe4__RelatedContact__c, rel.npe4__Contact__c));
        }

        // One relationship record per new pair, oriented child -> parent.
        // The NPSP trigger (List Setting reciprocal method) creates the
        // reciprocal parent -> child record via the Relationship Lookup.
        List<npe4__Relationship__c> newRelationships = new List<npe4__Relationship__c>();
        for (Id childId : validPairs.keySet()) {
            Id parentId = validPairs.get(childId);
            if (existingPairKeys.contains(pairKey(childId, parentId))) {
                continue;
            }
            newRelationships.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = TYPE_PARENT,
                npe4__Status__c = STATUS_CURRENT
            ));
        }

        // Single DML statement. Partial success keeps the import safe to
        // re-run: failed pairs were not saved, so they are not skipped as
        // "already existing" on the next run, while successful pairs are.
        if (!newRelationships.isEmpty()) {
            Database.insert(newRelationships, false);
        }
    }

    /**
     * Stable, orientation-independent key for a contact pair. Apex Ids are
     * 18 characters, so plain concatenation is collision-safe.
     */
    private static String pairKey(Id contactA, Id contactB) {
        return contactA + '-' + contactB;
    }
}
