/**
 * @description Reassigns ownership of Accounts and all of their Contacts to a new owner.
 *
 * Account trigger automation is intentionally bypassed (via the Trigger Actions
 * Framework transaction bypass) for the duration of the Account update, because
 * the Account trigger actions recalculate territories and are too expensive to
 * run for ownership-only changes. The bypass is always cleared in a `finally`
 * block, so Account automation behaves normally for the rest of the transaction
 * whether the operation succeeds or throws.
 *
 * Contact automation runs normally (no bypass is applied to Contact).
 *
 * DML is all-or-none (`update` without partial-success options) and exceptions
 * propagate unchanged to the caller.
 *
 * Bulk-safety: exactly one SOQL query (Contacts) and at most two DML statements
 * (one Account update, one Contact update), regardless of input volume.
 */
public inherited sharing class AccountOwnershipService {

    /**
     * @description Sets OwnerId on the given Accounts and on all Contacts of those Accounts.
     * @param accountIds Ids of the Accounts to reassign (up to 200 per call).
     * @param newOwnerId Id of the User (or Queue) that becomes the new owner.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        // Basic argument validation; we intentionally no-op on an empty set
        // so callers can pass through bulk collections without pre-filtering.
        if (newOwnerId == null) {
            throw new IllegalArgumentException('newOwnerId must not be null');
        }
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Build the Account update rows from the Ids directly: no SOQL needed,
        // since we only change OwnerId on records the caller already identified.
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            accountsToUpdate.add(new Account(Id = accountId, OwnerId = newOwnerId));
        }

        // Query 1 (of max 2): every Contact belonging to the given Accounts.
        List<Contact> contacts = [
            SELECT Id
            FROM Contact
            WHERE AccountId IN :accountIds
        ];

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact contact : contacts) {
            contactsToUpdate.add(new Contact(Id = contact.Id, OwnerId = newOwnerId));
        }

        // Bypass the entire Account sObject for this transaction so that none of
        // the registered Account trigger actions run for the ownership update.
        // Contact triggers are NOT bypassed and will run normally on the Contact update.
        TriggerBase.bypass(Schema.Account.SObjectType);
        try {
            // DML 1 (of max 2): all-or-none Account owner update, Account triggers bypassed.
            update accountsToUpdate;

            // DML 2 (of max 2): all-or-none Contact owner update, Contact triggers run fully.
            update contactsToUpdate;
        } finally {
            // Always restore Account automation, on success or on any exception,
            // so the rest of the transaction is unaffected by this bypass.
            TriggerBase.clearBypass(Schema.Account.SObjectType);
        }
    }
}
