/**
 * @description DML-less tests for the before-update trigger action
 *              TA_Opportunity_GuardAmountDecrease.
 *
 *              Following the Trigger Actions Framework (TAF) recommended pattern,
 *              no DML and no SOQL are executed: triggerNew / triggerOld lists are
 *              built in memory, records are given fake Ids via the package's
 *              TriggerTestUtility.getFakeId(...), and the action's beforeUpdate
 *              context method is invoked directly.
 *
 *              Errors are asserted through the SObject error API
 *              (hasErrors() / getErrors()) and compared against the action's
 *              ERROR_MESSAGE constant.
 *
 * @group       Trigger Actions Framework
 */
@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    /**
     * @description Invokes the action's beforeUpdate method directly, adapting the
     *              in-memory Opportunity lists to the List<SObject> signature
     *              declared by the TriggerAction.BeforeUpdate interface.
     */
    private static void runBeforeUpdate(List<Opportunity> newRecords, List<Opportunity> oldRecords) {
        List<SObject> triggerNew = new List<SObject>();
        List<SObject> triggerOld = new List<SObject>();
        for (Opportunity newRecord : newRecords) {
            triggerNew.add(newRecord);
        }
        for (Opportunity oldRecord : oldRecords) {
            triggerOld.add(oldRecord);
        }
        TriggerAction.BeforeUpdate action = new TA_Opportunity_GuardAmountDecrease();
        Test.startTest();
        action.beforeUpdate(triggerNew, triggerOld);
        Test.stopTest();
    }

    /**
     * @description Builds a single in-memory Opportunity with a fake Id, suitable
     *              for use in both the triggerNew and triggerOld lists.
     */
    private static Opportunity buildOpportunity(Id recordId, Decimal amount) {
        return new Opportunity(
            Id = recordId,
            Amount = amount
        );
    }

    /**
     * @description Asserts that the record carries exactly one error and that its
     *              message equals the action's ERROR_MESSAGE constant.
     */
    private static void assertSingleGuardError(SObject record) {
        Assert.isTrue(record.hasErrors(),
            'Expected the record to have errors, but hasErrors() returned false.');
        List<Database.Error> errors = record.getErrors();
        Assert.areEqual(1, errors.size(),
            'Expected exactly one error on the record but found: ' + errors.size());
        Assert.areEqual(TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE, errors.get(0).getMessage(),
            'The error message did not match the action\'s ERROR_MESSAGE constant.');
    }

    /**
     * @description Asserts that the record carries no errors at all.
     */
    private static void assertNoError(SObject record) {
        Assert.isFalse(record.hasErrors(),
            'Expected the record to be error-free, but hasErrors() returned true.');
    }

    @IsTest
    static void testReductionMoreThanHalfIsRejected() {
        Id recordId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        List<Opportunity> newRecords = new List<Opportunity>{
            buildOpportunity(recordId, 499)
        };
        List<Opportunity> oldRecords = new List<Opportunity>{
            buildOpportunity(recordId, 1000)
        };

        runBeforeUpdate(newRecords, oldRecords);

        assertSingleGuardError(newRecords.get(0));
    }

    @IsTest
    static void testReductionOfExactlyHalfIsAccepted() {
        Id recordId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        List<Opportunity> newRecords = new List<Opportunity>{
            buildOpportunity(recordId, 500)
        };
        List<Opportunity> oldRecords = new List<Opportunity>{
            buildOpportunity(recordId, 1000)
        };

        runBeforeUpdate(newRecords, oldRecords);

        assertNoError(newRecords.get(0));
    }

    @IsTest
    static void testIncreaseIsAccepted() {
        Id recordId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        List<Opportunity> newRecords = new List<Opportunity>{
            buildOpportunity(recordId, 2000)
        };
        List<Opportunity> oldRecords = new List<Opportunity>{
            buildOpportunity(recordId, 1000)
        };

        runBeforeUpdate(newRecords, oldRecords);

        assertNoError(newRecords.get(0));
    }

    @IsTest
    static void testNullPreviousAmountIsAcceptedWithoutException() {
        Id recordId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        List<Opportunity> newRecords = new List<Opportunity>{
            buildOpportunity(recordId, 250)
        };
        List<Opportunity> oldRecords = new List<Opportunity>{
            buildOpportunity(recordId, null)
        };

        // Must complete without throwing any exception.
        runBeforeUpdate(newRecords, oldRecords);

        assertNoError(newRecords.get(0));
    }

    @IsTest
    static void testMixedBatchOnlyOffendingRecordsGetErrors() {
        // Record 1: 1000 -> 400 (more than half reduced) => must be rejected.
        Id rejectedId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        // Record 2: 1000 -> 500 (exactly half reduced) => must be accepted.
        Id halvedId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        // Record 3: 1000 -> 1200 (increased) => must be accepted.
        Id increasedId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        // Record 4: null -> 300 (no previous Amount) => must be accepted.
        Id nullOldId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> newRecords = new List<Opportunity>{
            buildOpportunity(rejectedId, 400),
            buildOpportunity(halvedId, 500),
            buildOpportunity(increasedId, 1200),
            buildOpportunity(nullOldId, 300)
        };
        List<Opportunity> oldRecords = new List<Opportunity>{
            buildOpportunity(rejectedId, 1000),
            buildOpportunity(halvedId, 1000),
            buildOpportunity(increasedId, 1000),
            buildOpportunity(nullOldId, null)
        };

        runBeforeUpdate(newRecords, oldRecords);

        // Map the new records by Id so each outcome can be asserted precisely.
        Map<Id, Opportunity> newRecordsById = new Map<Id, Opportunity>(newRecords);

        assertSingleGuardError(newRecordsById.get(rejectedId));
        assertNoError(newRecordsById.get(halvedId));
        assertNoError(newRecordsById.get(increasedId));
        assertNoError(newRecordsById.get(nullOldId));
    }
}
