/**
 * @description Trigger Action that normalizes contact information on every Lead
 *              as it is created:
 *              - Email: trimmed and lower-cased (a null email stays null).
 *              - Company: trimmed.
 *              - LeadSource: defaulted to 'Web' when blank; an existing value is kept.
 *
 *              Runs in the before insert context, so the cleaned values are present
 *              on the first save. No DML and no SOQL — fields are mutated in place
 *              on trigger.new — and it is bulk-safe for any list size (e.g. 200 rows).
 *
 *              Registered via Trigger_Action__mdt (DeveloperName:
 *              TA_Lead_NormalizeContactInfo, Before_Insert__c = Lead, Order__c = 10).
 */
public inherited sharing class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {

    private static final String DEFAULT_LEAD_SOURCE = 'Web';

    /**
     * @description Normalizes Email, Company and LeadSource on every incoming Lead.
     * @param triggerNew The list of Leads being inserted, as provided by the
     *                   Trigger Actions Framework (MetadataTriggerHandler).
     */
    public void beforeInsert(List<SObject> triggerNew) {
        for (SObject record : triggerNew) {
            Lead lead = (Lead) record;

            lead.Email = normalizeEmail(lead.Email);
            lead.Company = trimWhitespace(lead.Company);

            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = DEFAULT_LEAD_SOURCE;
            }
        }
    }

    /**
     * @description Trims and lower-cases an email address. Null-safe: a null email
     *              stays null; a blank/whitespace-only email trims to an empty string.
     * @param email The raw email value.
     * @return The normalized email.
     */
    private static String normalizeEmail(String email) {
        if (String.isBlank(email)) {
            return email;
        }
        return email.trim().toLowerCase();
    }

    /**
     * @description Trims leading/trailing whitespace. Null-safe.
     * @param value The raw string value.
     * @return The trimmed value, or null if the input was null.
     */
    private static String trimWhitespace(String value) {
        if (value == null) {
            return null;
        }
        return value.trim();
    }
}
