public inherited sharing class TA_Case_RollupOpenCount
    implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {

    private Set<Id> affectedAccountIds = new Set<Id>();

    public void afterInsert(List<SObject> triggerNew) {
        collectAccountIds(triggerNew);
        recalculateOpenCaseCounts();
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Case newCase = (Case) triggerNew[i];
            Case oldCase = (Case) triggerOld[i];
            if (newCase.AccountId != oldCase.AccountId || newCase.IsClosed != oldCase.IsClosed) {
                addAccountId(newCase.AccountId);
                addAccountId(oldCase.AccountId);
            }
        }
        recalculateOpenCaseCounts();
    }

    public void afterDelete(List<SObject> triggerOld) {
        collectAccountIds(triggerOld);
        recalculateOpenCaseCounts();
    }

    public void afterUndelete(List<SObject> triggerNew) {
        collectAccountIds(triggerNew);
        recalculateOpenCaseCounts();
    }

    private void collectAccountIds(List<SObject> records) {
        for (SObject record : records) {
            addAccountId((Id) record.get('AccountId'));
        }
    }

    private void addAccountId(Id accountId) {
        if (accountId != null) {
            affectedAccountIds.add(accountId);
        }
    }

    private void recalculateOpenCaseCounts() {
        if (affectedAccountIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> openCountByAccountId = new Map<Id, Integer>();
        for (AggregateResult result : [
            SELECT AccountId, COUNT(Id) caseCount
            FROM Case
            WHERE IsClosed = false AND AccountId IN :affectedAccountIds
            GROUP BY AccountId
        ]) {
            openCountByAccountId.put(
                (Id) result.get('AccountId'),
                ((Decimal) result.get('caseCount')).intValue()
            );
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account account : [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :affectedAccountIds
        ]) {
            Integer newCount = openCountByAccountId.containsKey(account.Id)
                ? openCountByAccountId.get(account.Id)
                : 0;
            if (account.FB_Open_Case_Count__c == null || account.FB_Open_Case_Count__c != newCount) {
                accountsToUpdate.add(new Account(Id = account.Id, FB_Open_Case_Count__c = newCount));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
