public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    private static final String TASK_SUBJECT = 'Amount changed';

    /**
     * After-update action: whenever an Opportunity's Amount changes, create one
     * completed Task audit record on it.
     *
     * Recursion safety: TA_Opportunity_RoundAmount re-updates opportunities in the
     * same transaction, which re-runs this action. The framework counts how many
     * times each record has been seen in the after-update context per transaction
     * (TriggerBase.idToNumberOfTimesSeenAfterUpdate). We only log when a record is
     * seen for the first time in this transaction, so at most one "Amount changed"
     * Task is created per Opportunity per transaction, regardless of how many
     * recursive update cycles occur.
     *
     * Bulk safety: all Tasks are collected and inserted once per trigger execution.
     */
    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        Map<Id, Decimal> oldAmountsById = new Map<Id, Decimal>();
        for (Opportunity oldOpp : triggerOld) {
            oldAmountsById.put(oldOpp.Id, oldOpp.Amount);
        }

        Map<Id, Integer> idToNumberOfTimesSeenAfterUpdate = TriggerBase.idToNumberOfTimesSeenAfterUpdate;

        List<Task> auditTasks = new List<Task>();
        for (Opportunity opp : triggerNew) {
            Integer numberOfTimesSeen = idToNumberOfTimesSeenAfterUpdate.get(opp.Id);
            if (numberOfTimesSeen != null && numberOfTimesSeen > 1) {
                // Already processed this Opportunity in this transaction
                // (e.g. the re-update issued by the rounding action). Skip.
                continue;
            }
            if (isAmountChanged(opp.Amount, oldAmountsById.get(opp.Id))) {
                auditTasks.add(new Task(
                    Subject = TASK_SUBJECT,
                    WhatId = opp.Id,
                    Status = 'Completed'
                ));
            }
        }

        if (!auditTasks.isEmpty()) {
            insert auditTasks;
        }
    }

    /**
     * Amount is considered changed when it goes from null to a value, from a value
     * to null, or to a different value. Decimal equality in Apex compares numeric
     * value (not scale), so 100.0 vs 100.00 is not treated as a change.
     */
    private static Boolean isAmountChanged(Decimal newAmount, Decimal oldAmount) {
        if (newAmount == null && oldAmount == null) {
            return false;
        }
        if (newAmount == null || oldAmount == null) {
            return true;
        }
        return newAmount != oldAmount;
    }
}
