/**
 * Singleton holder for data queried on behalf of Contact trigger actions.
 *
 * The framework's recommended pattern for avoiding repeated queries: a single
 * inner `Service` trigger action runs first (Order__c = 1) in the before-insert
 * context, loads all parent Accounts needed by the records in this trigger
 * execution, and exposes them once via `getInstance().accountsById`. Later
 * actions read from the shared map instead of issuing their own SOQL.
 *
 * The map is reloaded on every trigger execution (every invocation of
 * `Service.beforeInsert`), because a later DML in the same transaction may
 * involve different Accounts; stale data must never be reused.
 */
public inherited sharing class TA_Contact_Queries {

    private static TA_Contact_Queries instance;

    /**
     * Parent Accounts for the current trigger execution, keyed by Id.
     * Populated by `Service` before any other before-insert action runs.
     */
    public Map<Id, Account> accountsById;

    private TA_Contact_Queries() {
        this.accountsById = new Map<Id, Account>();
    }

    /**
     * Returns the singleton instance for the current transaction.
     */
    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Trigger action that loads the shared Account map. Runs first in before
     * insert (Trigger_Action__mdt `TA_Contact_Queries_Service`, Order__c = 1).
     */
    public class Service implements TriggerAction.BeforeInsert {

        public void beforeInsert(List<SObject> triggerNew) {
            TA_Contact_Queries instance = getInstance();

            Set<Id> accountIds = new Set<Id>();
            for (SObject record : triggerNew) {
                Id accountId = ((Contact) record).AccountId;
                if (accountId != null) {
                    accountIds.add(accountId);
                }
            }

            // Reload on every trigger execution: later DML in the same
            // transaction can involve other Accounts.
            instance.accountsById = accountIds.isEmpty()
                ? new Map<Id, Account>()
                : new Map<Id, Account>([
                        SELECT Id,
                               BillingStreet,
                               BillingCity,
                               BillingPostalCode,
                               BillingCountry,
                               AccountSource
                        FROM Account
                        WHERE Id IN :accountIds]);
        }
    }
}
