/**
 * Contact before-insert trigger action: when a new Contact has an Account and
 * all four mailing fields (MailingStreet, MailingCity, MailingPostalCode,
 * MailingCountry) are blank, inherit the Account's billing address.
 *
 * Contacts without an Account, or with any mailing field already filled in,
 * keep their own address. No SOQL is performed here: the parent Accounts are
 * read from the shared map loaded by TA_Contact_Queries.Service.
 */
public inherited sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject record : triggerNew) {
            Contact contact = (Contact) record;

            if (contact.AccountId == null) {
                continue;
            }

            Account account = accountsById.get(contact.AccountId);
            if (account == null) {
                continue;
            }

            Boolean mailingStreetBlank = String.isBlank(contact.MailingStreet);
            Boolean mailingCityBlank = String.isBlank(contact.MailingCity);
            Boolean mailingPostalCodeBlank = String.isBlank(contact.MailingPostalCode);
            Boolean mailingCountryBlank = String.isBlank(contact.MailingCountry);

            if (mailingStreetBlank && mailingCityBlank
                    && mailingPostalCodeBlank && mailingCountryBlank) {
                contact.MailingStreet = account.BillingStreet;
                contact.MailingCity = account.BillingCity;
                contact.MailingPostalCode = account.BillingPostalCode;
                contact.MailingCountry = account.BillingCountry;
