/**
 * Contact before-insert trigger action: when a new Contact has an Account and
 * a blank LeadSource, default the LeadSource to the Account's AccountSource.
 *
 * Contacts without an Account, or with a LeadSource already populated, are
 * left alone. No SOQL is performed here: the parent Accounts are read from
 * the shared map loaded by TA_Contact_Queries.Service.
 */
public inherited sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject record : triggerNew) {
            Contact contact = (Contact) record;

            if (contact.AccountId == null || String.isNotBlank(contact.LeadSource)) {
                continue;
            }

            Account account = accountsById.get(contact.AccountId);
            if (account == null) {
                continue;
            }

            contact.LeadSource = account.AccountSource;
        }
    }
}
